SELECT percentile_cont(0.9) within GROUP (ORDER BY procedure_count) AS percentile_90, (SELECT AVG(los) FROM icustays WHERE subject_id IN (SELECT subject_id FROM age_range)) AS avg_los, (SELECT AVG(CASE WHEN d.deathtime IS NOT NULL THEN 1 ELSE 0 END) FROM patients p JOIN icustays i ON p.subject_id = i.subject_id WHERE p.subject_id IN (SELECT subject_id FROM age_range)) AS avg_mortality FROM procedure_counts;